import React from "react";

export default function App() {
  return (
    <>
      <style>{`
        *{
          margin:0;
          padding:0;
          box-sizing:border-box;
        }

        .home{
          position:relative;
          width:100%;
          height:100vh;
          overflow:hidden;
          background:black;
        }

        .bg-video{
          position:absolute;
          top:50%;
          left:50%;
          width:100%;
          height:100%;
          object-fit:cover;
          transform:translate(-50%, -50%);
          opacity:0.6;
        }

        .navbar{
          position:relative;
          z-index:10;
          width:100%;
          padding:20px 40px;
          color:white;
          font-size:22px;
          font-weight:bold;
        }
          @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500&display=swap');

.navbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #7a5c45; /* brown ناعم */
  padding: 14px 45px;
  font-family: 'Inter', sans-serif;
}

.logo {
  color: #f2eee9;
  font-size: 22px;
  font-weight: 500;
}

.nav-links {
  list-style: none;
  display: flex;
  gap: 32px;
}

.nav-links li a {
  color: #f0eae4;
  text-decoration: none;
  font-size: 15px;
  font-weight: 400;
  transition: 
    transform 0.35s ease,
    color 0.35s ease,
    opacity 0.35s ease;
  opacity: 0.85;
}

/* Hover ناعم بزاف */
.nav-links li a:hover {
  transform: scale(1.05); /* تكبير خفيف */
  color: #e6d6c3;        /* تغميق خفيف */
  opacity: 1;
}







        .center-text{

          position:absolute;
          top:50%;
          left:50%;
          transform:translate(-50%,-50%);
          color:#7a5c45;
          font-size:100px;
          font-weight:900;
          letter-spacing:3px;
          z-index:10;
          animation:popIn 1.3s ease forwards;
          opacity:0;
          
        }

        @keyframes popIn{
          0%{
            transform:translate(-50%,-50%) scale(0);
            opacity:0;
          }
          100%{
            transform:translate(-50%,-50%) scale(1);
            opacity:1;
          }
        }
      `}</style>

      <div className="home">
        <video className="bg-video" autoPlay loop muted playsInline>
          <source src="/vdbg.mp4" type="video/mp4" />
        </video>

        <nav className="navbar">
          
          <h2>M</h2>
          <ul className="nav-links">
            <li><a href="#home">Home</a></li>
            <li><a href="#history">History</a></li>
            <li><a href="#culture">Culture</a></li>
            <li><a href="#weather">Weather</a></li>
          </ul>
        </nav>

        <div className="center-text">
          Oujda City
        </div>
      </div>
    </>
  );
}
